/**
 * JSON Schema for validating mcp.json files.
 *
 * This schema matches the McpSpec TypeScript interface and can be used
 * with any JSON Schema validator (Ajv, Zod, etc.).
 */
const toolAnnotationsSchema = {
    type: "object",
    properties: {
        readOnlyHint: { type: "boolean" },
        destructiveHint: { type: "boolean" },
        idempotentHint: { type: "boolean" },
        openWorldHint: { type: "boolean" },
        title: { type: "string" },
    },
};
const resourceAnnotationsSchema = {
    type: "object",
    properties: {
        audience: {
            type: "array",
            items: { type: "string", enum: ["user", "assistant"] },
        },
        priority: { type: "number", minimum: 0, maximum: 1 },
    },
};
/**
 * A protocol revision is a date, so the shape is checked rather than the value.
 * An unknown but well-formed revision must validate: new revisions ship without
 * this package changing.
 */
const protocolVersionSchema = {
    type: "string",
    pattern: "^\\d{4}-\\d{2}-\\d{2}$",
    description: "MCP protocol revision (YYYY-MM-DD).",
};
const iconSchema = {
    type: "object",
    required: ["src"],
    properties: {
        src: { type: "string" },
        mimeType: { type: "string" },
        sizes: { type: "array", items: { type: "string" } },
        theme: { type: "string", enum: ["light", "dark"] },
    },
};
const iconsProperty = {
    type: "array",
    items: iconSchema,
};
const jsonSchemaRef = {
    type: "object",
    description: "A JSON Schema definition.",
};
const toolSchema = {
    type: "object",
    required: ["name", "inputSchema"],
    properties: {
        name: { type: "string" },
        description: { type: "string" },
        title: { type: "string" },
        inputSchema: {
            type: "object",
            required: ["type"],
            properties: {
                type: { const: "object" },
                properties: { type: "object" },
                required: { type: "array", items: { type: "string" } },
            },
        },
        outputSchema: jsonSchemaRef,
        annotations: toolAnnotationsSchema,
        icons: iconsProperty,
    },
};
const resourceSchema = {
    type: "object",
    required: ["uri", "name"],
    properties: {
        uri: { type: "string" },
        name: { type: "string" },
        description: { type: "string" },
        mimeType: { type: "string" },
        size: { type: "number" },
        annotations: resourceAnnotationsSchema,
        icons: iconsProperty,
    },
};
const resourceTemplateSchema = {
    type: "object",
    required: ["uriTemplate", "name"],
    properties: {
        uriTemplate: { type: "string" },
        name: { type: "string" },
        description: { type: "string" },
        mimeType: { type: "string" },
        annotations: resourceAnnotationsSchema,
        icons: iconsProperty,
    },
};
const promptArgumentSchema = {
    type: "object",
    required: ["name"],
    properties: {
        name: { type: "string" },
        description: { type: "string" },
        required: { type: "boolean" },
    },
};
const promptSchema = {
    type: "object",
    required: ["name"],
    properties: {
        name: { type: "string" },
        description: { type: "string" },
        arguments: { type: "array", items: promptArgumentSchema },
        icons: iconsProperty,
    },
};
const serverInfoSchema = {
    type: "object",
    required: ["name", "version"],
    properties: {
        name: { type: "string" },
        version: { type: "string" },
        description: { type: "string" },
        websiteUrl: { type: "string" },
        icons: iconsProperty,
    },
};
const capabilitiesSchema = {
    type: "object",
    properties: {
        tools: {
            type: "object",
            properties: { listChanged: { type: "boolean" } },
        },
        resources: {
            type: "object",
            properties: {
                subscribe: { type: "boolean" },
                listChanged: { type: "boolean" },
            },
        },
        prompts: {
            type: "object",
            properties: { listChanged: { type: "boolean" } },
        },
        logging: { type: "object" },
        completions: { type: "object" },
        experimental: { type: "object" },
    },
};
const transportSchema = {
    type: "object",
    required: ["type"],
    properties: {
        type: { type: "string", enum: ["stdio", "sse", "streamable-http"] },
        command: { type: "string" },
        args: { type: "array", items: { type: "string" } },
        env: { type: "object" },
        url: { type: "string" },
    },
};
/**
 * JSON Schema for the root McpSpec document (mcp.json).
 *
 * @example
 * ```ts
 * import Ajv from "ajv";
 * import { mcpSpecSchema } from "mcp-schema/schema";
 *
 * const ajv = new Ajv();
 * const validate = ajv.compile(mcpSpecSchema);
 * const valid = validate(mySpec);
 * ```
 */
export const mcpSpecSchema = {
    type: "object",
    required: ["mcpSpec", "server"],
    properties: {
        mcpSpec: {
            type: "string",
            description: "MCP Spec format version (semver).",
        },
        mcpVersion: protocolVersionSchema,
        mcpVersions: {
            type: "array",
            items: protocolVersionSchema,
            description: "Every protocol revision the server reports it supports.",
        },
        server: serverInfoSchema,
        description: {
            type: "string",
            description: "Extended server description (markdown supported).",
        },
        capabilities: capabilitiesSchema,
        transport: transportSchema,
        tools: { type: "array", items: toolSchema },
        resources: { type: "array", items: resourceSchema },
        resourceTemplates: { type: "array", items: resourceTemplateSchema },
        prompts: { type: "array", items: promptSchema },
        $defs: { type: "object" },
    },
};
